private val accentNumbers = intArrayOf(100, 200, 400, 700)
private fun nearestShade(shades: IntArray, shade: Int) = shades.indices.minBy { kotlin.math.abs(shades[it] - shade) }
/** A palette colour: [shade] 50, 100, 200, ..., 900 (another number gives the nearest). */
fun materialColor(hue: MaterialHue, shade: Int = 500) = colorFromHex(materialShades[hue.ordinal][nearestShade(shadeNumbers, shade)])
/** An accent, A100 to A700; brown, grey and blue grey have none, and give their plain shade of the number. */
fun materialAccent(hue: MaterialHue, shade: Int = 200): Vec4 {
    val i = nearestShade(accentNumbers, shade)
    val accent = materialAccents[hue.ordinal][i]
    return if (accent != 0u) colorFromHex(accent) else materialColor(hue, accentNumbers[i])
}
